    /**
     * automatizacion_unidaddocActions::executeCreate
     * @return void retorna la vista asociada a este actions
    */
    public function executeUpdate(sfWebRequest $request)
    {
        $status = 200;
        $message_error = "Actividad realizada exitosamente";
        //***********************************************************************************************************
        try{
            $usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
            //$this->verificaPrilegioCerrar('automatizacion_unidaddoc/create');
            $post_parameters = $request->getPostParameters();
            //*******************************************************************************************************
            if (empty(trim($post_parameters['expedientereglas_id'])))
            {
                $expediente_reglas = new ExpedienteReglas();
                //***************************************************************************************************
                $expediente_reglas_anterior = clone $expediente_reglas;
                //***************************************************************************************************
                $expediente_reglas->setFechaCreacion(date("Y-m-d G:i:s"));
                $expediente_reglas->setFechaModificacion(date("Y-m-d G:i:s"));
                $expediente_reglas->setUsuarioId($usuariologuiado);
            }
            else
            {
                $expediente_reglas = ExpedienteReglasPeer::retrieveByPk($post_parameters['expedientereglas_id']);
                $expediente_reglas->setFechaModificacion(date("Y-m-d G:i:s"));
                $this->forward404Unless($expediente_reglas);
            }
            //*******************************************************************************************************
            $subserie_id = !empty(trim($post_parameters['autsubserie_id'])) ? trim($post_parameters['autsubserie_id']) : null;
            $tipoexpregla_id = !empty(trim($post_parameters['tipoexpedientereglas_id'])) ? trim($post_parameters['tipoexpedientereglas_id']) : null;
            $nombre_regla = !empty(trim($post_parameters['nombre_regla'])) ? trim($post_parameters['nombre_regla']) : null;
            $descripcion_regla = !empty(trim($post_parameters['descripcion_regla'])) ? trim($post_parameters['descripcion_regla']) : null;
            $modulo_id = !empty(trim($post_parameters['modulo_id'])) ? trim($post_parameters['modulo_id']) : null;
            $tipocom_id = !empty(trim($post_parameters['tipocom_id'])) ? trim($post_parameters['tipocom_id']) : null;
            $autotipodocumental_id = !empty(trim($post_parameters['autotipodocumental_id'])) ? trim($post_parameters['autotipodocumental_id']) : null;
            $texto_base = !empty(trim($post_parameters['texto_base'])) ? trim($post_parameters['texto_base']) : null;
            $separator_text = !empty(trim($post_parameters['separator_text'])) ? trim($post_parameters['separator_text']) : null;
            $auto_exp_etiqueta = count($post_parameters['auto_exp_etiqueta']) ? $post_parameters['auto_exp_etiqueta'] : null;
            $auto_metaetiquetas = count($post_parameters['etiquetas_orden']) ? preg_split("/[,]/", $post_parameters['etiquetas_orden'], -1, PREG_SPLIT_NO_EMPTY) : null;
            $texto_compuesto = !empty(trim($post_parameters['texto_compuesto'])) ? trim($post_parameters['texto_compuesto']) : null;
            //*******************************************************************************************************
            $expediente_reglas->setSubserieId($subserie_id);
            $expediente_reglas->setTipoexpedientereglasId($tipoexpregla_id);
            $expediente_reglas->setModuloId($modulo_id);
            $expediente_reglas->setTipodocumentalId($autotipodocumental_id);
            $expediente_reglas->setTipocomId($tipocom_id);
            $expediente_reglas->setNombreRegla($nombre_regla);
            $expediente_reglas->setDescripcionRegla($descripcion_regla);
            $expediente_reglas->setTextoBase($texto_base);
            $expediente_reglas->setSeparadorText($separator_text);
            $expediente_reglas->setTextoCompuesto($texto_compuesto);
            $expediente_reglas->save();
            //*******************************************************************************************************
            $orden_etiqueta = 0;
            foreach ($auto_metaetiquetas as $row_etiqueta) {
                $data_info = preg_split("/[_]/", $row_etiqueta, -1, PREG_SPLIT_NO_EMPTY);
                //***************************************************************************************************
                $_object = new ExpedienteReglaEtiqueta();
                $_object->setExpedientereglasId($expediente_reglas->getPrimaryKey());
                $_object->setExpedienteetiquetaId($data_info[0]);
                $_object->setOrden(++$orden_etiqueta);
                $_object->save();
            }
            //*******************************************************************************************************
            AuditLogPeer::guardarAuditoriaLite(ExpedienteReglasPeer::getOMClass(),$expediente_reglas_anterior,$expediente_reglas,
                ModulesEnable::Seguridad,$expediente_reglas->getPrimaryKey(),$usuariologuiado);
        }catch(PropelException $ex){
            $status = 400;
            $message_error = "Error acceso a la base de datos";
        }catch(\Exception $ex){
            $status = 400;
            $message_error = "Error interno de la aplicacion,{$ex->getMessage()}";
        }catch(\Throwable $ex){
            $status = 400;
            $message_error = "Error interno del servidor,{$ex->getMessage()}";
        }
        //***********************************************************************************************************
        $response_info['status'] = $status;
        $response_info['message'] = $message_error;
        $this->getResponse()->setContentType('application/json');
        return $this->renderText(json_encode($response_info));
    }

    /**
     * automatizacion_unidaddocActions::executeUpdateNewEtiqueta
     * @return void retorna la vista asociada a este actions
    */
    public function executeUpdateNewEtiqueta()
    {
        $usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
        //$this->verificaPrilegioCerrar('automatizacion_unidaddoc/create_etiqueta');
        //*******************************************************************************************************
        if (!$this->getRequestParameter('expedienteetiqueta_id'))
        {
            $expediente_etiqueta = new ExpedienteEtiqueta();
            //***************************************************************************************************
            $expediente_etiqueta_anterior = clone $expediente_etiqueta;
            //***************************************************************************************************
            $expediente_etiqueta->setFechaCreacion(date("Y-m-d G:i:s"));
            $expediente_etiqueta->setFechaModificacion(date("Y-m-d G:i:s"));
            $expediente_etiqueta->setUsuarioId($usuariologuiado);
        }
        else
        {
            $expediente_etiqueta = ExpedienteEtiquetaPeer::retrieveByPk($this->getRequestParameter('expedienteetiqueta_id'));
            $expediente_etiqueta->setFechaModificacion(date("Y-m-d G:i:s"));
            $this->forward404Unless($expediente_etiqueta);
        }
        //*******************************************************************************************************
        $modulo_id = !empty(trim($this->getRequestParameter('modulo_id'))) ? trim($this->getRequestParameter('modulo_id')) : 0;
        $nombre_etiqueta = !empty(trim($this->getRequestParameter('nombre'))) ? trim($this->getRequestParameter('nombre')) : null;
        $desc_etiqueta = !empty(trim($this->getRequestParameter('descripcion'))) ? trim($this->getRequestParameter('descripcion')) : null;
        $modulo_metadato = !empty(trim($this->getRequestParameter('modulo_metadato'))) ? SED::decryption(trim($this->getRequestParameter('modulo_metadato'))) : null;
        $nombre_interno = str_replace(' ','',ucwords($nombre_etiqueta));
        //*******************************************************************************************************
        $str_metadato = preg_split("/[.]/",$modulo_metadato,-1,PREG_SPLIT_NO_EMPTY);
        if(count($str_metadato) != 2){
            $this->getUser()->setFlash('messages_error', 'Error al descomponer el metadato de origen');
            $this->redirect($this->getRequest()->getScriptName() . '/automatizacion_unidaddoc/newEtiqueta?modulo_id=' . $modulo_id);
        }
        //*******************************************************************************************************
        if(empty($modulo_id)){
            $this->getUser()->setFlash('messages_error', 'Error el modulo es un dato obligatorio');
            $this->redirect($this->getRequest()->getScriptName() . '/automatizacion_unidaddoc/newEtiqueta?modulo_id=' . $modulo_id);
        }
        //*******************************************************************************************************
        $class_peer = "{$str_metadato[0]}Peer";
        //*******************************************************************************************************
        $table_origen = $class_peer::TABLE_NAME;
        $object_class = $class_peer::OM_CLASS;
        $field_origen = $str_metadato[1];
        $method_origen = "get{$str_metadato[1]}";
        //*******************************************************************************************************
        $columnName = call_user_func(array($class_peer, 'translateFieldName'), 
            $field_origen,
            BasePeer::TYPE_PHPNAME, 
            BasePeer::TYPE_FIELDNAME
        );
        //*******************************************************************************************************
        $test_object = new $object_class;
        if(!method_exists($test_object,$method_origen)){
            $this->getUser()->setFlash('messages_error', 'Error el campo de origen no puede ser leido');
            $this->redirect($this->getRequest()->getScriptName() . '/automatizacion_unidaddoc/newEtiqueta?modulo_id=' . $modulo_id);
        }else{
            $test_object = null;
        }
        //*******************************************************************************************************
        if(empty(trim($nombre_etiqueta)) || empty(trim($desc_etiqueta)) || empty(trim($nombre_interno))
            || empty(trim($table_origen)) || empty(trim($object_class)) || empty(trim($field_origen))){
            $this->getUser()->setFlash('messages_error', 'Ocurrio un error, algunos parametros no son validos');
            $this->redirect($this->getRequest()->getScriptName() . '/automatizacion_unidaddoc/newEtiqueta?modulo_id=' . $modulo_id);
        }
        //*******************************************************************************************************
        $expediente_etiqueta->setModuloId($modulo_id);
        $expediente_etiqueta->setNombre($nombre_etiqueta);
        $expediente_etiqueta->setDescripcion($desc_etiqueta);
        $expediente_etiqueta->setNombreInterno($nombre_interno);
        $expediente_etiqueta->setTablaOrigen($table_origen);
        $expediente_etiqueta->setCampoOrigen($columnName);
        $expediente_etiqueta->setObjectClass($object_class);
        $expediente_etiqueta->save();
        //*******************************************************************************************************
        AuditLogPeer::guardarAuditoriaLite(ExpedienteEtiquetaPeer::getOMClass(),$expediente_etiqueta_anterior,$expediente_etiqueta,
            ModulesEnable::Seguridad,$expediente_etiqueta->getPrimaryKey(),$usuariologuiado);
        //*******************************************************************************************************
        $ietiquetas = ExpedienteEtiquetaPeer::getExpedienteEtiquetasByModulo($expediente_etiqueta->getModuloId());
        foreach ($ietiquetas as $row_etiqueta) {
            $id_etiqueta = sprintf("%s_%s",$row_etiqueta->getPrimaryKey(),strtoupper($row_etiqueta->getNombreInterno()));
            $resp_ietiquetas[] = array('id' => $id_etiqueta, 'text' => $row_etiqueta->getNombreInterno());
        }
        //*******************************************************************************************************
        $this->list_ietiquetas = $resp_ietiquetas;
        $this->expediente_etiqueta = $expediente_etiqueta;
        //*******************************************************************************************************
        $this->forward404Unless($expediente_etiqueta);
    }

    /**
     * automatizacion_unidaddocActions::getCriteriaBasic
     * @param Criteria objeto criteria principal el cual se adicionaran los filtros 
     * basado en los parametros del formulario de consulta
     * @return Criteria retorna objeto criteria con los filtros aplicados
    */
    private function getCriteriaBasic(Criteria $c)
    {
        $usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
        //***********************************************************************************************
        //$c->addJoin(EmailPeer::EMAILACCOUNT_ID,EmailAccountPeer::EMAILACCOUNT_ID,Criteria::INNER_JOIN);
        //$c->addJoin(EmailAccountPeer::EMAILACCOUNT_ID,EmailAccountUsuarioPeer::EMAILACCOUNT_ID,Criteria::INNER_JOIN);
        //***********************************************************************************************
        if (!empty(trim($this->getRequestParameter('nombre_regla')))) {
            $c->add(ExpedienteReglasPeer::NOMBRE_REGLA, '%' . trim($this->getRequestParameter('nombre_regla')) . '%', Criteria::LIKE);
            $this->parametros .= "&nombre_regla=" . trim($this->getRequestParameter('nombre_regla'));
        }
        //***********************************************************************************************
        if (!empty(trim($this->getRequestParameter('descripcion_regla')))) {
            $c->add(ExpedienteReglasPeer::DESCRIPCION_REGLA, '%' . trim($this->getRequestParameter('descripcion_regla')) . '%', Criteria::LIKE);
            $this->parametros .= "&descripcion_regla=" . trim($this->getRequestParameter('descripcion_regla'));
        }
        //***********************************************************************************************
        if (!empty(trim($this->getRequestParameter('subserie_id')))) {
            $c->add(ExpedienteReglasPeer::SUBSERIE_ID, trim($this->getRequestParameter('subserie_id')));
            $this->parametros .= "&subserie_id=" . trim($this->getRequestParameter('subserie_id'));
        }
        //***********************************************************************************************
        if (!empty(trim($this->getRequestParameter('modulo_id')))) {
            $c->add(ExpedienteReglasPeer::MODULO_ID, trim($this->getRequestParameter('modulo_id')));
            $this->parametros .= "&modulo_id=" . trim($this->getRequestParameter('modulo_id'));
        }
        //***********************************************************************************************
        if (!empty(trim($this->getRequestParameter('tipoexpedientereglas_id')))) {
            $c->add(ExpedienteReglasPeer::TIPOEXPEDIENTEREGLAS_ID, trim($this->getRequestParameter('tipoexpedientereglas_id')));
            $this->parametros .= "&tipoexpedientereglas_id=" . trim($this->getRequestParameter('tipoexpedientereglas_id'));
        }
        //***********************************************************************************************
        $c->addDescendingOrderByColumn(ExpedienteReglasPeer::FECHA_CREACION);
        //***********************************************************************************************
        return $c;
    }
}